size_t RegisterMPCImage(void)
{
  MagickInfo
    *magick_info;

  magick_info = AcquireMagickInfo("MPC", "MPC", "Magick Persistent Cache");
  magick_info->description = ConstantString("Magick Persistent Cache");
  magick_info->magick = MPCImage;
  magick_info->decoder = (ImageDecoder) ReadMPCImage;
  magick_info->encoder = (ImageEncoder) WriteMPCImage;
  magick_info->adjoin = MagickTrue;
  (void) RegisterMagickInfo(magick_info);
  return sizeof(*magick_info);
}
